1	import { Editor, TLShape, TLShapePartial } from "tldraw";
2	import { MtgCardShape } from "../../shared/mtgCardShape";
3	import { findOpenSpotsNearZoneEdge, Rect } from "./openSpotNearZoneEdge";
4	import { topmostZoneAt, ZoneHit } from "./zoneHitTest";
5	import { PASSENGER_TYPES } from "./cardPassengers";
6	
7	
8	const NON_BATTLEFIELD_ZONES = new Set(["graveyard", "exile", "library"]);
9	
10	/** A card landing on top of this much of another card's area reads as "hidden behind it". */
11	const STACK_OVERLAP_THRESHOLD = 0.6;
12	/** How far right to nudge a card that lands directly on another, so both stay visible. */
13	const STACK_LANDING_NUDGE = 40;
14	const MAX_LANDING_ATTEMPTS = 10;
15	
16	export function handleTranslateEnd(editor: Editor, current: MtgCardShape): TLShapePartial<MtgCardShape> | undefined {
17	  const zoneHit = zoneAt(editor, current);
18	  const zone = zoneHit?.zone;
19	  const previousZone = (current.meta?.zone as string | undefined) ?? undefined;
20	  if (zone === previousZone) return undefined;
21	
22	  if (zoneHit) {
23	
24	    if (NON_BATTLEFIELD_ZONES.has(zoneHit.zone)) {
25	      evictPassengers(editor, current, zoneHit);
26	    }
27	  }
28	
29	  const resetFace = zoneHit?.zone === "library" && (current.props.face !== "front" || current.props.faceDown);
30	  const landingX = zoneHit?.zone === "stack" ? nudgeOffAnotherCard(editor, current) : undefined;
31	
32	  return {
33	    id: current.id,
34	    type: current.type,
35	    ...(landingX !== undefined ? { x: landingX } : {}),
36	    ...(resetFace ? { props: { ...current.props, face: "front" as const, faceDown: false } } : {}),
37	    meta: { ...current.meta, zone: zone ?? null },
38	  };
39	}
40	
41	/** If the card just landed square on top of another one on the Stack, step it right until both show. */
42	function nudgeOffAnotherCard(editor: Editor, current: MtgCardShape): number | undefined {
43	  const bounds = editor.getShapePageBounds(current);
44	  if (!bounds) return undefined;
45	
46	  let dx = 0;
47	  for (let attempt = 0; attempt < MAX_LANDING_ATTEMPTS; attempt++) {
48	    const candidate: Rect = { x: bounds.x + dx, y: bounds.y, w: bounds.w, h: bounds.h };
49	    const hidesAnotherCard = editor.getCurrentPageShapes().some((shape) => {
50	      if (shape.type !== "mtg-card" || shape.id === current.id) return false;
51	      const other = editor.getShapePageBounds(shape);
52	      return !!other && overlapFraction(candidate, other) >= STACK_OVERLAP_THRESHOLD;
53	    });
54	    if (!hidesAnotherCard) return attempt === 0 ? undefined : current.x + dx;
55	    dx += STACK_LANDING_NUDGE;
56	  }
57	  return current.x + dx;
58	}
59	
60	function overlapFraction(a: Rect, b: Rect): number {
61	  const overlapW = Math.max(0, Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x));
62	  const overlapH = Math.max(0, Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y));
63	  return (overlapW * overlapH) / (a.w * a.h);
64	}
65	
66	function zoneAt(editor: Editor, shape: MtgCardShape): ZoneHit | undefined {
67	  const bounds = editor.getShapePageBounds(shape);
68	  return bounds ? topmostZoneAt(editor, bounds.center) : undefined;
69	}
70	
71	function evictPassengers(editor: Editor, card: MtgCardShape, zoneHit: ZoneHit): void {
72	  const passengers = editor
73	    .getSortedChildIdsForParent(card.id)
74	    .map((id) => editor.getShape(id))
75	    .filter((s): s is TLShape => !!s && PASSENGER_TYPES.has(s.type));
76	  if (passengers.length === 0) return;
77	
78	  const zoneBounds = editor.getShapePageBounds(zoneHit.id);
79	  const cardBounds = editor.getShapePageBounds(card);
80	  if (!zoneBounds || !cardBounds) return;
81	
82	  const passengerIds = new Set(passengers.map((p) => p.id));
83	  const occupied: Rect[] = [];
84	  for (const shape of editor.getCurrentPageShapes()) {
85	    if (shape.type !== "mtg-card" && !PASSENGER_TYPES.has(shape.type)) continue;
86	    if (passengerIds.has(shape.id)) continue;
87	    const bounds = editor.getShapePageBounds(shape);
88	    if (bounds) occupied.push({ x: bounds.x, y: bounds.y, w: bounds.w, h: bounds.h });
89	  }
90	
91	  const spotSize = editor.getShapeGeometry(passengers[0]).bounds.w;
92	  const spots = findOpenSpotsNearZoneEdge({
93	    zone: { x: zoneBounds.x, y: zoneBounds.y, w: zoneBounds.w, h: zoneBounds.h },
94	    entry: { x: cardBounds.center.x, y: cardBounds.center.y },
95	    spotSize,
96	    occupied,
97	    count: passengers.length,
98	  });
99	
100	  editor.reparentShapes(
101	    passengers.map((p) => p.id),
102	    editor.getCurrentPageId(),
103	  );
104	  editor.animateShapes(
105	    passengers.map((p, i) => ({ id: p.id, type: p.type, x: spots[i].x, y: spots[i].y, rotation: 0 })),
106	    { animation: { duration: 200 } },
107	  );
108	}
